    function link(n, cur, badge) { const key = n[0]; const active = cur === key || (cur === 'product' && key === 'products') || (cur === 'case' && key === 'cases'); return `<a href="#/${key}" ${active ? 'aria-current="page"' : ''}><svg viewBox="0 0 24 24"><path d="${n[2]}"/></svg>${n[1]}${badge ? `<span class="n ${badge ? 'hot' : ''}">${badge}</span>` : ''}</a>`; }
