        <div class="card kpi ${certs.some(c => c.days <= 30) ? 'hot' : ''}"><div class="lbl">성적서 만료 임박</div><div class="val"><span data-count="${certs.length}">0</span><small>건 (60일 내)</small></div><div class="sub">${certs[0] ? `${certs[0].p.name} D-${certs[0].days}` : '없음'}</div></div>
