    const list = all.filter(x => inboxState.tab === 'spam' ? x.flags.spam : (!x.flags.spam && (inboxState.tab === 'all' || x.type === inboxState.tab))).filter(x => !inboxState.status || x.status === inboxState.status).filter(x => !inboxState.q || (x.no + x.name + (x.company || '') + (x.phone || '') + (x.snapshotNote || '') + (x.message || '')).includes(inboxState.q)).sort((a, b) => b.createdAt - a.createdAt);
    setTop('접수함', `견적·샘플·상담 ${all.filter(x => !x.flags.spam).length}건`, `<button class="btn btn--s" id="exp-csv">CSV 내보내기</button>`);
    main().innerHTML = `<div class="card pad0"><div class="tabs" role="tablist">${tabs.map(t => `<button role="tab" aria-selected="${inboxState.tab === t[0]}" data-tab="${t[0]}">${t[1]}<span class="n">${t[2]}</span></button>`).join('')}</div>
      <div class="toolbar"><label class="search"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg><input placeholder="접수번호 · 이름 · 연락처 · 내용" value="${esc(inboxState.q)}" id="ib-q"></label>${['', 'new', 'checked', 'shipped', 'replied', 'done'].map(s => `<button class="chip" data-st="${s}" aria-pressed="${inboxState.status === s}">${s ? A.STATUS[s] : '모든 상태'}</button>`).join('')}<span class="sp"></span><span class="sub" style="color:var(--ink-2)">응대 목표 영업일 ${S.responseTargetHours}시간 · 경과 색: 1시간 · 목표 · 24시간</span></div>
      <div class="tbl-wrap"><table class="tbl"><thead><tr><th>접수번호</th><th>유형</th><th>신청자</th><th>내용</th><th>접수 시각</th><th>경과</th><th>상태</th><th>알림</th><th></th></tr></thead><tbody>${list.map(it => `<tr class="${id === it.id ? 'is-sel' : ''}" data-open="${it.id}" style="cursor:pointer"><td class="ttl">${esc(it.no)}</td><td>${A.TYPE[it.type]}</td><td>${esc(it.name)}<div class="sub">${esc(it.phone)}${it.kind === 'biz' ? ' · ' + esc(it.company) : ''}</div></td><td><div style="max-width:360px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(it.snapshotNote || (it.items && it.items.length ? '샘플 ' + it.items.length + '개 — ' + it.items.map(i => (A.byId('products', i) || {}).name).filter(Boolean).join(', ') : it.message) || '')}</div><div style="display:flex;gap:4px;margin-top:2px">${it.flags.fire ? '<span class="badge b-fire">방화 검토</span>' : ''}${it.flags.resubmit ? '<span class="badge b-neu">재신청</span>' : ''}${it.flags.spam ? `<span class="badge b-spam" title="${esc(it.flags.spamReason)}">스팸 의심</span>` : ''}</div></td><td class="sub">${fmt.date(it.createdAt)} ${fmt.time(it.createdAt)}</td><td>${['new', 'checked'].includes(it.status) ? elapsed(it) : '<span class="sub">—</span>'}</td><td>${statusBadge(it.status)}</td><td>${it.notify.length ? (it.notify.every(n => n.ok) ? `<span class="badge b-done">${it.notify.length}/${it.notify.length}</span>` : `<span class="badge b-late">${it.notify.filter(n => n.ok).length}/${it.notify.length}</span>`) : '<span class="sub">—</span>'}</td><td class="acts"><button class="btn btn--sm btn--s" data-open="${it.id}">열기</button></td></tr>`).join('') || `<tr><td colspan="9" class="empty"><b>해당하는 접수가 없습니다</b>공개 사이트에서 견적 의뢰·샘플 신청을 제출하면 여기에 즉시 나타납니다.</td></tr>`}</tbody></table></div></div>`;
    $$('[data-tab]').forEach(b => b.addEventListener('click', () => { inboxState.tab = b.dataset.tab; inbox(); }));
