    $('#exp-csv').addEventListener('click', () => { A.logAccess('내보내기', `접수함 ${list.length}건`); const rows = [['접수번호', '유형', '상태', '접수시각', '이름(마스킹)', '연락처(마스킹)', '유형', '회사', '내용', '방화검토', '재신청']].concat(list.map(it => [it.no, A.TYPE[it.type], A.STATUS[it.status], fmt.date(it.createdAt) + ' ' + fmt.time(it.createdAt), it.name, it.phone, it.kind === 'biz' ? '사업자' : '개인', it.company || '', (it.snapshotNote || it.message || '').replace(/^[=+\-@]/, "'$&"), it.flags.fire ? 'Y' : '', it.flags.resubmit ? 'Y' : ''])); A.download(`argilo_접수함_${fmt.date(now()).replace(/\./g, '')}.csv`, A.csv(rows), 'text/csv;charset=utf-8'); toast('CSV를 내려받았습니다 — 개인정보는 마스킹 상태, 접속기록에 남았습니다', 'ok'); });
