    const flow = it.type === 'sample' ? ['new', 'checked', 'shipped', 'done', 'followup'] : it.type === 'quote' ? ['new', 'checked', 'replied', 'done'] : ['new', 'checked', 'replied', 'done'];
    const idx = flow.indexOf(it.status);
